import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

/**
 * Combobox — Base UI Combobox foundation (Phase 5).
 *
 * Public API preserved: options/value/onValueChange/multiple, async
 * (filter=false + onSearchChange), creatable (Wensity-owned action row),
 * label/hint/error, status icons, sizes, and multi-selection summary.
 *
 * D-17: onOpenChange → (open: boolean) => void.
 *
 * Tokens: solid `--primitive-surface-overlay` + `--primitive-shadow-overlay`
 * for the popup surface. Trigger heights/radius come from the control family
 * (`--primitive-control-height-*`, `--primitive-radius-control`).
 */

import * as React from "react";
import { Combobox as BaseCombobox } from "@base-ui/react/combobox";
import { IconPlus, IconSearch } from "@tabler/icons-react";
import { cn } from "@/lib/utils";

export type ComboboxSize = "sm" | "md" | "lg";
export type ComboboxStatus = "default" | "error" | "success";

export type ComboboxOption = {
  value: string;
  label: React.ReactNode;
  description?: React.ReactNode;
  leading?: React.ReactNode;
  disabled?: boolean;
};

export type ComboboxGroup = {
  label?: React.ReactNode;
  options: ComboboxOption[];
};

export interface ComboboxProps {
  id?: string;
  options: ComboboxOption[] | ComboboxGroup[];
  value?: string | string[];
  defaultValue?: string | string[];
  onValueChange?: (value: string | string[]) => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  multiple?: boolean;
  creatable?: boolean;
  onCreateOption?: (inputValue: string) => ComboboxOption | void;
  createLabel?: (inputValue: string) => React.ReactNode;
  loading?: boolean;
  onSearchChange?: (query: string) => void;
  /** Client-side filter. Set false when options are driven by `onSearchChange`. */
  filter?: boolean;
  name?: string;
  required?: boolean;
  disabled?: boolean;
  label?: React.ReactNode;
  hint?: React.ReactNode;
  error?: React.ReactNode;
  success?: React.ReactNode;
  status?: ComboboxStatus;
  placeholder?: string;
  emptyMessage?: React.ReactNode;
  /** Screen reader copy when nothing is selected in `multiple` mode. */
  emptySelectionLabel?: React.ReactNode;
  /** Close the list when every selectable option is chosen in `multiple` mode. */
  closeWhenAllSelected?: boolean;
  comboboxSize?: ComboboxSize;
  fullWidth?: boolean;
  leadingIcon?: React.ReactNode;
  containerClassName?: string;
  triggerClassName?: string;
  contentClassName?: string;
  "aria-describedby"?: string;
  "aria-invalid"?: boolean | "true" | "false";
  "aria-required"?: boolean | "true" | "false";
}

/** Sentinel value used for the Wensity "create new" action row. */
const CREATE_SENTINEL = "__wensity_combobox_create__";

const triggerHeights: Record<ComboboxSize, string> = {
  sm: "min-h-[var(--primitive-control-height-sm)] text-xs",
  md: "min-h-[var(--primitive-control-height-md)] text-sm",
  lg: "min-h-[var(--primitive-control-height-lg)] text-[15px]",
};

const inputHeights: Record<ComboboxSize, string> = {
  sm: "px-3",
  md: "px-3.5",
  lg: "px-4",
};

const contentWidths: Record<ComboboxSize, string> = {
  sm: "min-w-[12rem]",
  md: "min-w-[15rem]",
  lg: "min-w-[17rem]",
};

const overlaySurfaceClass = cn(
  "border border-[var(--border)] bg-[var(--primitive-surface-overlay)] text-[var(--foreground)]",
  "[box-shadow:var(--primitive-shadow-overlay)]",
);

const popupMotionClass = cn(
  "origin-[var(--transform-origin)] transform-gpu outline-none",
  "transition-[opacity,scale] duration-[180ms] ease-[var(--primitive-ease,cubic-bezier(0.23,1,0.32,1))]",
  "data-[ending-style]:duration-[120ms]",
  "data-[starting-style]:opacity-0 data-[ending-style]:opacity-0",
  "data-[starting-style]:scale-[0.96] data-[ending-style]:scale-[0.96]",
  "motion-reduce:transition-none motion-reduce:data-[starting-style]:scale-100 motion-reduce:data-[ending-style]:scale-100",
);

function adaptOpenChange(
  onOpenChange?: (open: boolean) => void,
): ((open: boolean, details: unknown) => void) | undefined {
  if (!onOpenChange) return undefined;
  return (open) => onOpenChange(open);
}

function isGroupedOptions(
  options: ComboboxOption[] | ComboboxGroup[],
): options is ComboboxGroup[] {
  return options.length > 0 && "options" in options[0];
}

function flattenOptions(options: ComboboxOption[] | ComboboxGroup[]) {
  return isGroupedOptions(options)
    ? options.flatMap((group) => group.options)
    : options;
}

function getOptionLabelText(option: ComboboxOption) {
  return typeof option.label === "string" || typeof option.label === "number"
    ? String(option.label)
    : option.value;
}

function buildMultipleFieldSummary(
  selectedOptions: ComboboxOption[],
  selectedCount: number,
  totalSelectable: number,
) {
  if (selectedCount === 0) return null;
  if (totalSelectable > 0 && selectedCount >= totalSelectable) {
    return totalSelectable === 1
      ? getOptionLabelText(selectedOptions[0]!)
      : `All ${totalSelectable} selected`;
  }
  if (selectedCount === 1 && selectedOptions[0]) {
    return getOptionLabelText(selectedOptions[0]);
  }
  const first = selectedOptions[0] ? getOptionLabelText(selectedOptions[0]) : "";
  const remaining = selectedCount - 1;
  return remaining > 0 ? `${first} + ${remaining} more` : first;
}

function countSelectableOptions(options: ComboboxOption[]) {
  return options.filter((option) => !option.disabled).length;
}

function normalizeValue(
  value: string | string[] | undefined,
  multiple: boolean,
): string | string[] {
  if (multiple) {
    if (Array.isArray(value)) return value;
    if (value) return [value];
    return [];
  }
  return Array.isArray(value) ? (value[0] ?? "") : (value ?? "");
}

/** ButtonSpinner recipe — canonical loading indicator (PRIM-MOTION-002). */
function ButtonSpinner({ className }: { className?: string }) {
  return (
    <span
      aria-hidden
      className={cn(
        "size-3.5 shrink-0 rounded-full border-2 border-current border-r-transparent opacity-80 motion-safe:animate-spin",
        className,
      )}
    />
  );
}

function ComboboxSuccessCheck() {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 16 16"
      fill="none"
      className="size-4 text-[var(--primitive-success)]"
    >
      <path
        d="M3.25 8.1 6.35 11.2 12.75 4.6"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

function ComboboxErrorX() {
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 16 16"
      fill="none"
      className="size-4 text-[var(--primitive-destructive)]"
    >
      <path
        d="M4.5 4.5 11.5 11.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
      <path
        d="M11.5 4.5 4.5 11.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
      />
    </svg>
  );
}

export function Combobox({
  options,
  id,
  value,
  defaultValue,
  onValueChange,
  open: controlledOpen,
  defaultOpen,
  onOpenChange,
  multiple = false,
  creatable = false,
  onCreateOption,
  createLabel,
  loading = false,
  onSearchChange,
  filter = true,
  name,
  required,
  disabled,
  label,
  hint,
  error,
  success,
  status: statusProp,
  placeholder = "Search…",
  emptyMessage = "No results found.",
  emptySelectionLabel = "Nothing selected.",
  closeWhenAllSelected = true,
  comboboxSize = "md",
  fullWidth = true,
  leadingIcon,
  containerClassName,
  triggerClassName,
  contentClassName,
  "aria-describedby": ariaDescribedBy,
  "aria-invalid": ariaInvalid,
  "aria-required": ariaRequired,
}: ComboboxProps) {
  const reactId = React.useId();
  const comboboxId = id ?? `wensity-combobox-${reactId}`;
  const labelId = label ? `${comboboxId}-label` : undefined;
  const hintId = hint ? `${comboboxId}-hint` : undefined;
  const errorId = error ? `${comboboxId}-error` : undefined;
  const successId = success ? `${comboboxId}-success` : undefined;

  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(
    defaultOpen ?? false,
  );
  const [uncontrolledValue, setUncontrolledValue] = React.useState(() =>
    normalizeValue(defaultValue, multiple),
  );
  const [inputValue, setInputValue] = React.useState("");
  const [createdOptions, setCreatedOptions] = React.useState<ComboboxOption[]>([]);

  const open = controlledOpen ?? uncontrolledOpen;
  const selectedValue = value ?? uncontrolledValue;

  const authoredOptions = React.useMemo(() => flattenOptions(options), [options]);
  const localCreatedOptions = React.useMemo(() => {
    if (createdOptions.length === 0) return [];
    const authoredValues = new Set(authoredOptions.map((option) => option.value));
    return createdOptions.filter((option) => !authoredValues.has(option.value));
  }, [authoredOptions, createdOptions]);
  const flattenedOptions = React.useMemo(
    () =>
      localCreatedOptions.length > 0
        ? [...authoredOptions, ...localCreatedOptions]
        : authoredOptions,
    [authoredOptions, localCreatedOptions],
  );

  const resolvedStatus: ComboboxStatus =
    statusProp ?? (error ? "error" : success ? "success" : "default");

  const selectedValues = multiple
    ? Array.isArray(selectedValue)
      ? selectedValue
      : []
    : selectedValue
      ? [selectedValue as string]
      : [];

  const selectedOptions = flattenedOptions.filter((option) =>
    selectedValues.includes(option.value),
  );
  const selectableCount = countSelectableOptions(flattenedOptions);
  const hasSelection = selectedValues.length > 0;
  const allSelected =
    multiple && hasSelection && selectableCount > 0 && selectedValues.length >= selectableCount;

  const describedBy =
    [ariaDescribedBy, errorId, successId, hintId].filter(Boolean).join(" ") ||
    undefined;

  const filterQuery = filter ? inputValue.trim().toLowerCase() : "";

  const filteredFlat = React.useMemo(() => {
    if (!filterQuery) return flattenedOptions;
    return flattenedOptions.filter((option) => {
      const labelText = getOptionLabelText(option).toLowerCase();
      const descriptionText =
        typeof option.description === "string"
          ? option.description.toLowerCase()
          : "";
      return (
        labelText.includes(filterQuery) ||
        option.value.toLowerCase().includes(filterQuery) ||
        descriptionText.includes(filterQuery)
      );
    });
  }, [filterQuery, flattenedOptions]);

  const canCreate =
    creatable &&
    inputValue.trim().length > 0 &&
    !flattenedOptions.some(
      (option) =>
        getOptionLabelText(option).toLowerCase() === inputValue.trim().toLowerCase() ||
        option.value.toLowerCase() === inputValue.trim().toLowerCase(),
    );

  const setOpen = React.useCallback(
    (next: boolean) => {
      if (controlledOpen === undefined) setUncontrolledOpen(next);
      onOpenChange?.(next);
    },
    [controlledOpen, onOpenChange],
  );

  const commitValue = React.useCallback(
    (next: string | string[]) => {
      if (value === undefined) setUncontrolledValue(next);
      onValueChange?.(next);
    },
    [onValueChange, value],
  );

  const performCreate = React.useCallback(() => {
    const trimmed = inputValue.trim();
    if (!trimmed || !creatable) return;

    const created = onCreateOption?.(trimmed) ?? {
      value: trimmed.toLowerCase().replace(/\s+/g, "-"),
      label: trimmed,
    };

    if (!created) return;
    setCreatedOptions((current) =>
      current.some((option) => option.value === created.value) ? current : [...current, created],
    );

    if (multiple) {
      const current = Array.isArray(selectedValue) ? selectedValue : [];
      if (!current.includes(created.value)) {
        commitValue([...current, created.value]);
      }
    } else {
      commitValue(created.value);
      setOpen(false);
    }
    setInputValue("");
    onSearchChange?.("");
  }, [
    commitValue,
    creatable,
    inputValue,
    multiple,
    onCreateOption,
    onSearchChange,
    selectedValue,
    setOpen,
  ]);

  const handleValueChange = React.useCallback(
    (next: string | string[] | null) => {
      // Base UI reports `null` for single-select clear; normalize to "".
      const normalized = multiple
        ? Array.isArray(next)
          ? next
          : []
        : ((next as string | null) ?? "");

      if (multiple && Array.isArray(normalized) && normalized.includes(CREATE_SENTINEL)) {
        // Strip the sentinel; performCreate will add the real option below.
        performCreate();
        return;
      }
      if (!multiple && normalized === CREATE_SENTINEL) {
        performCreate();
        return;
      }

      commitValue(normalized);

      if (
        multiple &&
        Array.isArray(normalized) &&
        closeWhenAllSelected &&
        selectableCount > 0 &&
        normalized.length >= selectableCount
      ) {
        setOpen(false);
      } else if (!multiple) {
        setOpen(false);
      }
    },
    [
      closeWhenAllSelected,
      commitValue,
      multiple,
      performCreate,
      selectableCount,
      setOpen,
    ],
  );

  const handleInputValueChange = React.useCallback(
    (next: string) => {
      setInputValue(next);
      onSearchChange?.(next);
    },
    [onSearchChange],
  );

  const handleInputKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLInputElement>) => {
      if (
        event.key === "Backspace" &&
        multiple &&
        !inputValue &&
        selectedValues.length
      ) {
        commitValue(selectedValues.slice(0, -1));
      }
    },
    [commitValue, inputValue, multiple, selectedValues],
  );

  const multipleFieldSummary =
    multiple && !open
      ? buildMultipleFieldSummary(
          selectedOptions,
          selectedValues.length,
          selectableCount,
        )
      : null;

  const inputPlaceholder =
    open && multiple && hasSelection ? "Search to add or remove…" : placeholder;

  const adaptedOnValueChange = React.useCallback(
    (next: string | string[] | null) => {
      handleValueChange(next);
    },
    [handleValueChange],
  );

  const rootValue = multiple ? selectedValues : ((selectedValues[0] ?? null) as string | null);

  const renderOptionRow = (option: ComboboxOption) => {
    const isSelected = selectedValues.includes(option.value);
    return (
      <BaseCombobox.Item
        key={option.value}
        value={option.value}
        disabled={option.disabled}
        className={cn(
          "group/combobox-item relative flex min-h-9 cursor-default select-none items-center gap-3",
          "rounded-[var(--primitive-radius-item)] px-2.5 py-2 pr-9 text-sm outline-none",
          "text-[var(--foreground)]",
          "data-[disabled]:pointer-events-none data-[disabled]:opacity-40",
          "data-[highlighted]:bg-[var(--primitive-surface-selected)]",
          isSelected && "bg-[var(--primitive-surface-selected)]",
        )}
      >
        {option.leading ? (
          <span className="grid size-7 shrink-0 place-items-center rounded-[var(--primitive-radius-control-sm)] border border-[var(--border)] bg-[var(--primitive-surface-hover)] text-[var(--muted-foreground)] [&_svg]:size-4">
            {option.leading}
          </span>
        ) : null}
        <span className="flex min-w-0 flex-1 items-baseline gap-2">
          <span className="min-w-0 truncate font-medium tracking-[-0.01em]">
            {option.label}
          </span>
          {option.description ? (
            <span className="min-w-0 flex-1 truncate text-[12px] leading-none text-[var(--primitive-text-secondary)]">
              {option.description}
            </span>
          ) : null}
        </span>
        <BaseCombobox.ItemIndicator className="absolute right-3 top-1/2 -translate-y-1/2 text-[var(--foreground)]">
          <svg aria-hidden="true" viewBox="0 0 16 16" fill="none" className="size-3.5">
            <path
              d="M3.4 8.2 6.45 11.25 12.6 4.75"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        </BaseCombobox.ItemIndicator>
      </BaseCombobox.Item>
    );
  };

  return (
    <div
      className={cn(
        "flex flex-col gap-1.5",
        fullWidth ? "w-full" : "w-fit",
        containerClassName,
      )}
    >
      {label ? (
        <label
          id={labelId}
          htmlFor={comboboxId}
          className="text-[13px] font-medium leading-none tracking-[-0.01em] text-[var(--foreground)]"
        >
          {label}
        </label>
      ) : null}

      <BaseCombobox.Root data-wensity-primitive=""
        id={comboboxId}
        name={name}
        required={required}
        disabled={disabled}
        open={open}
        onOpenChange={adaptOpenChange(setOpen)}
        inputValue={inputValue}
        onInputValueChange={(next) => handleInputValueChange(next)}
        // Disable Base UI internal filtering — we filter/render ourselves so
        // that grouped headings, creatable rows, and Backspace-clear-last
        // (multi mode) stay Wensity-owned.
        filter={null}
        autoHighlight
        multiple={multiple as false}
        value={rootValue as string | null}
        onValueChange={adaptedOnValueChange as (v: string | null) => void}
      >
        <BaseCombobox.InputGroup
          data-status={resolvedStatus}
          data-has-selection={hasSelection ? "" : undefined}
          data-all-selected={allSelected ? "" : undefined}
          className={cn(
            "group/combobox relative flex items-center gap-2",
            "rounded-[var(--primitive-radius-control)] border border-[var(--border)] bg-[var(--background)]",
            "transition-[background-color,border-color,box-shadow] duration-160 ease-[var(--primitive-ease)]",
            "hover:border-[color-mix(in_srgb,var(--foreground)_16%,transparent)]",
            "focus-within:border-[color-mix(in_srgb,var(--foreground)_24%,transparent)]",
            "data-[popup-open]:border-[color-mix(in_srgb,var(--foreground)_24%,transparent)]",
            resolvedStatus === "error" &&
              "border-[var(--primitive-destructive-border)] data-[popup-open]:border-[var(--primitive-destructive)]",
            triggerHeights[comboboxSize],
            disabled && "cursor-not-allowed opacity-45",
            triggerClassName,
          )}
        >
          <span className="inline-flex shrink-0 pl-3 text-[var(--muted-foreground)] [&_svg]:size-4">
            {leadingIcon ?? <IconSearch stroke={1.75} aria-hidden="true" />}
          </span>

          <div className="relative flex min-h-0 min-w-0 flex-1 items-center self-stretch py-0.5">
            {multipleFieldSummary ? (
              <span
                aria-hidden="true"
                className={cn(
                  "pointer-events-none absolute inset-y-0 left-0 flex max-w-[calc(100%-0.25rem)] items-center truncate text-sm font-medium tracking-[-0.015em] text-[var(--foreground)]",
                  allSelected && "text-[var(--primitive-success)]",
                )}
              >
                {multipleFieldSummary}
              </span>
            ) : null}

            <BaseCombobox.Input
              disabled={disabled}
              aria-invalid={ariaInvalid ?? (error ? true : undefined)}
              aria-describedby={describedBy}
              aria-required={ariaRequired ?? required ?? undefined}
              aria-busy={loading || undefined}
              aria-labelledby={labelId}
              placeholder={multipleFieldSummary ? undefined : inputPlaceholder}
              onKeyDown={handleInputKeyDown}
              className={cn(
                "w-full min-w-0 border-0 bg-transparent text-[var(--foreground)] outline-none",
                "placeholder:text-[var(--primitive-text-placeholder)]",
                "disabled:cursor-not-allowed",
                inputHeights[comboboxSize],
                "px-0",
                multipleFieldSummary && !open && "text-transparent caret-[var(--foreground)]",
              )}
            />
          </div>

          {multiple && hasSelection ? (
            <span
              aria-hidden="true"
              className={cn(
                "shrink-0 tabular-nums text-[11px] font-medium tracking-[-0.01em]",
                allSelected
                  ? "text-[var(--primitive-success)]"
                  : "text-[var(--muted-foreground)]",
              )}
            >
              {selectedValues.length}/{selectableCount}
            </span>
          ) : null}

          {resolvedStatus === "success" && !allSelected ? (
            <span aria-hidden="true" className="shrink-0">
              <ComboboxSuccessCheck />
            </span>
          ) : null}
          {resolvedStatus === "error" ? (
            <span aria-hidden="true" className="shrink-0">
              <ComboboxErrorX />
            </span>
          ) : null}

          {loading ? (
            <span
              aria-hidden="true"
              className="mr-3 inline-flex shrink-0 text-[var(--muted-foreground)]"
            >
              <ButtonSpinner />
            </span>
          ) : (
            <BaseCombobox.Trigger
              disabled={disabled}
              className={cn(
                "mr-2 inline-flex size-6 shrink-0 items-center justify-center rounded-[var(--primitive-radius-control-sm)] text-[var(--muted-foreground)]",
                "transition-transform duration-[220ms] ease-[var(--primitive-ease)] motion-reduce:transition-none",
                "data-[popup-open]:rotate-180",
                "hover:text-[var(--foreground)]",
              )}
              aria-label="Toggle options"
            >
              <svg viewBox="0 0 16 16" fill="none" className="size-4">
                <path
                  d="m4.25 6.25 3.75 3.5 3.75-3.5"
                  stroke="currentColor"
                  strokeWidth="1.7"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </BaseCombobox.Trigger>
          )}
        </BaseCombobox.InputGroup>

        <BaseCombobox.Portal>
          <BaseCombobox.Positioner
            align="start"
            sideOffset={8}
            collisionPadding={12}
            className="z-[var(--primitive-z-popover)] outline-none"
          >
            <BaseCombobox.Popup data-wensity-primitive=""
              initialFocus={false}
              className={cn(
                overlaySurfaceClass,
                "relative max-h-[min(22rem,var(--available-height))] w-[var(--anchor-width)] overflow-x-hidden overflow-y-auto",
                "rounded-[var(--primitive-radius-surface)] p-1.5 text-[var(--foreground)]",
                contentWidths[comboboxSize],
                popupMotionClass,
                contentClassName,
              )}
            >
              {multiple && (filteredFlat.length > 0 || canCreate) ? (
                <div className="mb-1 flex items-center justify-between gap-3 border-b border-[var(--border)] px-2.5 pb-2 pt-1">
                  <span className="text-[11px] font-medium tracking-[-0.01em] text-[var(--muted-foreground)]">
                    {selectedValues.length} of {selectableCount} selected
                  </span>
                  {allSelected ? (
                    <span className="text-[11px] font-medium text-[var(--primitive-success)]">
                      Complete
                    </span>
                  ) : null}
                </div>
              ) : null}

              <BaseCombobox.List className="space-y-0.5 outline-none">
                {loading && filteredFlat.length === 0 ? (
                  <div
                    role="status"
                    className="flex min-h-16 items-center justify-center gap-2 px-3 text-[12px] text-[var(--muted-foreground)]"
                  >
                    <ButtonSpinner />
                    Loading…
                  </div>
                ) : filteredFlat.length === 0 && !canCreate ? (
                  <div
                    role="status"
                    className="px-3 py-6 text-center text-[12px] text-[var(--muted-foreground)]"
                  >
                    {emptyMessage}
                  </div>
                ) : (
                  <>
                    {isGroupedOptions(options)
                      ? options.map((group, groupIndex) => {
                          const visible = group.options.filter((option) =>
                            filteredFlat.some((match) => match.value === option.value),
                          );
                          if (visible.length === 0) return null;
                          return (
                            <BaseCombobox.Group
                              key={groupIndex}
                              items={visible}
                            >
                              {group.label ? (
                                <BaseCombobox.GroupLabel className="px-2.5 pb-1 pt-2 text-[11px] font-semibold uppercase tracking-[0.07em] text-[var(--muted-foreground)]">
                                  {group.label}
                                </BaseCombobox.GroupLabel>
                              ) : null}
                              {visible.map((option) => renderOptionRow(option))}
                            </BaseCombobox.Group>
                          );
                        })
                      : filteredFlat.map((option) => renderOptionRow(option))}

                    {isGroupedOptions(options) && localCreatedOptions.length > 0
                      ? localCreatedOptions
                          .filter((option) =>
                            filteredFlat.some((match) => match.value === option.value),
                          )
                          .map((option) => renderOptionRow(option))
                      : null}

                    {canCreate ? (
                      <BaseCombobox.Item
                        value={CREATE_SENTINEL}
                        className={cn(
                          "flex w-full min-h-9 cursor-default items-center gap-2.5",
                          "rounded-[var(--primitive-radius-item)] px-2.5 py-2 text-left text-sm outline-none",
                          "text-[var(--foreground)]",
                          "data-[highlighted]:bg-[var(--primitive-surface-selected)]",
                        )}
                      >
                        <span className="grid size-7 shrink-0 place-items-center rounded-[var(--primitive-radius-control-sm)] border border-[var(--border)] bg-[var(--primitive-surface-hover)] text-[var(--muted-foreground)]">
                          <IconPlus stroke={1.75} className="size-4" />
                        </span>
                        <span className="min-w-0 flex-1 truncate font-medium tracking-[-0.01em]">
                          {createLabel
                            ? createLabel(inputValue.trim())
                            : `Create "${inputValue.trim()}"`}
                        </span>
                      </BaseCombobox.Item>
                    ) : null}
                  </>
                )}
              </BaseCombobox.List>
            </BaseCombobox.Popup>
          </BaseCombobox.Positioner>
        </BaseCombobox.Portal>
      </BaseCombobox.Root>

      {error ? (
        <p
          id={errorId}
          className="text-[12px] leading-[1.45] font-medium text-[var(--primitive-destructive)]"
        >
          {error}
        </p>
      ) : success ? (
        <p
          id={successId}
          className="text-[12px] leading-[1.45] font-medium text-[var(--primitive-success)]"
        >
          {success}
        </p>
      ) : hint ? (
        <p id={hintId} className="text-[12px] leading-[1.45] text-[var(--primitive-text-secondary)]">
          {hint}
        </p>
      ) : null}
    </div>
  );
}
